const FRAME=320;const PREBUFFER=960;const MAXBUF=3200;const ALVO=1280;class VoipIO extends AudioWorkletProcessor{constructor(options){super();const po=options&&options.processorOptions||{};this.pre=po.pre>0?po.pre:PREBUFFER;this.max=po.max>0?po.max:MAXBUF;this.alvo=po.alvo>0?po.alvo:ALVO;this.ring=new Float32Array(16e3*2);this.wr=0;this.rd=0;this.filled=0;this.primed=false;this.outAccum=new Float32Array(FRAME);this.outLen=0;this.port.onmessage=e=>{if(!e.data||e.data.kind!=="in")return;const i16=new Int16Array(e.data.pcm);for(let i=0;i<i16.length;i++){this.ring[this.wr]=i16[i]/32768;this.wr=(this.wr+1)%this.ring.length;if(this.filled<this.ring.length)this.filled++;else this.rd=(this.rd+1)%this.ring.length}}}process(inputs,outputs){const mic=inputs[0]&&inputs[0][0];if(mic){for(let i=0;i<mic.length;i++){this.outAccum[this.outLen++]=mic[i];if(this.outLen===FRAME){const i16=new Int16Array(FRAME);for(let k=0;k<FRAME;k++){let v=this.outAccum[k];v=v>1?1:v<-1?-1:v;i16[k]=v*32767}this.port.postMessage({kind:"out",pcm:i16.buffer},[i16.buffer]);this.outLen=0}}}const out=outputs[0][0];if(this.filled>this.max){const pular=this.filled-this.alvo;this.rd=(this.rd+pular)%this.ring.length;this.filled-=pular}if(!this.primed&&this.filled>=this.pre)this.primed=true;for(let i=0;i<out.length;i++){if(this.primed&&this.filled>0){out[i]=this.ring[this.rd];this.rd=(this.rd+1)%this.ring.length;this.filled--}else{out[i]=0;if(this.primed&&this.filled===0)this.primed=false}}return true}}registerProcessor("voip-io",VoipIO);